import type { LineBarChartColors } from './types';

const LABEL_TO_SERIES_KEY: Record<string, keyof LineBarChartColors> = {
  'last year': 'lastYear',
  ly: 'lastYear',
  budget: 'budget',
  bu: 'budget',
  current: 'current',
  'current year': 'current',
  ac: 'current',
};

const normalizeLabel = (label?: string): string =>
  label?.trim().toLowerCase() ?? '';

export const getSeriesColorByLabel = (
  label: string | undefined,
  chartColors: LineBarChartColors,
): string => {
  const seriesKey = LABEL_TO_SERIES_KEY[normalizeLabel(label)] ?? 'current';
  return chartColors[seriesKey] ?? chartColors.current;
};

export const isBudgetSeriesLabel = (label?: string): boolean => {
  const normalized = normalizeLabel(label);
  return normalized === 'budget' || normalized === 'bu';
};
